"""gitignore-style pattern matching. See task.md."""

from __future__ import annotations

from dataclasses import dataclass


class PatternError(ValueError):
    """Raised for a malformed character class or a dangling escape."""


def _strip_trailing_spaces(line: str) -> str:
    while line.endswith(" "):
        i = len(line) - 1
        j = i - 1
        backslashes = 0
        while j >= 0 and line[j] == "\\":
            backslashes += 1
            j -= 1
        if backslashes % 2 == 1:
            break
        line = line[:i]
    return line


def _find_class_end(text: str, start: int) -> int:
    """`start` is the index right after `[` or `[!`. Returns index of the closing `]`."""
    n = len(text)
    j = start
    first = True
    while True:
        if j >= n:
            raise PatternError("unterminated character class")
        c = text[j]
        if c == "\\":
            if j + 1 >= n:
                raise PatternError("dangling backslash in character class")
            j += 2
            first = False
            continue
        if c == "]" and not first:
            return j
        j += 1
        first = False


def _compile_class(text: str, i: int):
    """`text[i] == '['`. Returns (token, next_index)."""
    n = len(text)
    j = i + 1
    negate = False
    if j < n and text[j] == "!":
        negate = True
        j += 1
    body_start = j
    end = _find_class_end(text, j)
    body = text[body_start:end]
    next_i = end + 1

    atoms = []
    bi = 0
    bn = len(body)
    while bi < bn:
        c = body[bi]
        if c == "\\":
            atoms.append(("esc", body[bi + 1]))
            bi += 2
        elif c == "-":
            atoms.append(("dash", None))
            bi += 1
        else:
            atoms.append(("chr", c))
            bi += 1

    m = len(atoms)
    is_literal_dash = [a[0] == "dash" and (idx == 0 or idx == m - 1) for idx, a in enumerate(atoms)]

    def decode(a):
        return "-" if a[0] == "dash" else a[1]

    chars = set()
    ranges = []
    idx = 0
    while idx < m:
        a = atoms[idx]
        if a[0] == "dash":
            chars.add("-")
            idx += 1
            continue
        ch = decode(a)
        if (
            idx + 1 < m
            and atoms[idx + 1][0] == "dash"
            and not is_literal_dash[idx + 1]
            and idx + 2 < m
        ):
            end_ch = decode(atoms[idx + 2])
            if ord(end_ch) < ord(ch):
                raise PatternError("character range is out of order")
            ranges.append((ch, end_ch))
            idx += 3
        else:
            chars.add(ch)
            idx += 1

    return ("class", negate, chars, ranges), next_i


def _compile_segment(text: str):
    """Compile a single path segment's text (no `/`) into a token list."""
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c == "\\":
            if i + 1 >= n:
                raise PatternError("dangling backslash")
            tokens.append(("lit", text[i + 1]))
            i += 2
        elif c == "*":
            j = i
            while j < n and text[j] == "*":
                j += 1
            tokens.append(("star",))
            i = j
        elif c == "?":
            tokens.append(("any",))
            i += 1
        elif c == "[":
            token, i = _compile_class(text, i)
            tokens.append(token)
        else:
            tokens.append(("lit", c))
            i += 1
    return tokens


def _match_tokens(tokens, s: str) -> bool:
    def rec(ti: int, si: int) -> bool:
        if ti == len(tokens):
            return si == len(s)
        tok = tokens[ti]
        if tok[0] == "star":
            for k in range(si, len(s) + 1):
                if rec(ti + 1, k):
                    return True
            return False
        if si >= len(s):
            return False
        ch = s[si]
        if tok[0] == "lit":
            if ch != tok[1]:
                return False
        elif tok[0] == "any":
            pass
        elif tok[0] == "class":
            _, negate, chars, ranges = tok
            in_set = ch in chars or any(lo <= ch <= hi for lo, hi in ranges)
            if negate:
                in_set = not in_set
            if not in_set:
                return False
        return rec(ti + 1, si + 1)

    return rec(0, 0)


def _match_path_segments(pat_segments, path_segments) -> bool:
    def rec(pi: int, si: int) -> bool:
        if pi == len(pat_segments):
            return si == len(path_segments)
        seg = pat_segments[pi]
        if seg == "**":
            if pi == len(pat_segments) - 1:
                return len(path_segments) - si >= 1
            for k in range(si, len(path_segments) + 1):
                if rec(pi + 1, k):
                    return True
            return False
        if si >= len(path_segments):
            return False
        if _match_tokens(seg, path_segments[si]):
            return rec(pi + 1, si + 1)
        return False

    return rec(0, 0)


@dataclass
class _CompiledPattern:
    negate: bool
    dir_only: bool
    anchored: bool
    segments: list


def _compile_pattern(line: str):
    line = _strip_trailing_spaces(line)
    if line == "":
        return None
    if line.startswith("#"):
        return None

    negate = False
    if line.startswith("!"):
        negate = True
        line = line[1:]

    dir_only = False
    if line.endswith("/"):
        dir_only = True
        line = line[:-1]

    if line == "":
        return None

    anchored = "/" in line
    if anchored and line.startswith("/"):
        line = line[1:]

    segment_texts = line.split("/")
    if anchored:
        segments = [seg if seg == "**" else _compile_segment(seg) for seg in segment_texts]
    else:
        segments = [_compile_segment(segment_texts[0])]

    return _CompiledPattern(negate=negate, dir_only=dir_only, anchored=anchored, segments=segments)


def is_ignored(patterns: list[str], path: str, is_dir: bool) -> bool:
    """Return True when `path` is ignored by `patterns`."""
    compiled = [c for c in (_compile_pattern(p) for p in patterns) if c is not None]

    path_segments = path.split("/")
    basename = path_segments[-1]

    decision = False
    for pat in compiled:
        if pat.dir_only and not is_dir:
            continue
        if pat.anchored:
            matched = _match_path_segments(pat.segments, path_segments)
        else:
            matched = _match_tokens(pat.segments[0], basename)
        if matched:
            decision = not pat.negate

    return decision
